    def maxProfit(self, prices: List[int], profits: List[int]) -> int:
        n = len(prices)
        max_profit = -1
        for j in range(1, n - 1):
            max_i_profit = -1
            max_k_profit = -1
            for i in range(j):
                if prices[i] < prices[j]:
                    max_i_profit = max(max_i_profit, profits[i])
            for k in range(j + 1, n):
                if prices[j] < prices[k]:
                    max_k_profit = max(max_k_profit, profits[k])
            if max_i_profit != -1 and max_k_profit != -1:
